-- Journey V2.7 stabilization: make declared block imports real and reject silent partial imports.
REVOKE INSERT ON public.journey_content_reports FROM authenticated;
CREATE OR REPLACE FUNCTION public.englify_admin_stage_journey_import(p_request_id uuid,p_filename text,p_format text,p_rows jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE batch public.journey_import_batches; row record; data jsonb; errors jsonb; valid int:=0; entity text;
BEGIN IF NOT public.englify_is_admin() THEN RAISE EXCEPTION 'Administrator access required' USING ERRCODE='42501'; END IF; IF p_request_id IS NULL OR p_format NOT IN ('csv','xlsx') OR jsonb_typeof(p_rows)<>'array' OR jsonb_array_length(p_rows) NOT BETWEEN 1 AND 500 OR length(p_filename)>180 THEN RAISE EXCEPTION 'Invalid import batch' USING ERRCODE='22023'; END IF;
 SELECT * INTO batch FROM public.journey_import_batches WHERE created_by=auth.uid() AND request_id=p_request_id; IF FOUND THEN RETURN jsonb_build_object('batch_id',batch.id,'replayed',true,'row_count',batch.row_count,'valid_count',(SELECT count(*) FROM public.journey_import_rows WHERE batch_id=batch.id AND jsonb_array_length(validation_errors)=0),'rows',(SELECT jsonb_agg(to_jsonb(r) ORDER BY row_number) FROM public.journey_import_rows r WHERE batch_id=batch.id)); END IF;
 INSERT INTO public.journey_import_batches(created_by,request_id,filename,format,row_count) VALUES(auth.uid(),p_request_id,p_filename,p_format,jsonb_array_length(p_rows)) RETURNING * INTO batch;
 FOR row IN SELECT value,ordinality FROM jsonb_array_elements(p_rows) WITH ORDINALITY LOOP data:=row.value;entity:=data->>'entity';errors:='[]';
  IF entity NOT IN ('chapter','unit','lesson','block') OR coalesce(data->>'external_id','') !~ '^[A-Za-z0-9_-]{1,80}$' THEN errors:=errors||jsonb_build_array('invalid entity or external_id'); END IF;
  IF entity IN ('chapter','unit','lesson') AND (length(btrim(coalesce(data->>'title','')))=0 OR coalesce(data->>'slug','') !~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' OR coalesce((data->>'position')::int,0)<1) THEN errors:=errors||jsonb_build_array('invalid title, slug, or position'); END IF;
  IF entity IN ('unit','lesson','block') AND coalesce(data->>'parent_external_id','')='' THEN errors:=errors||jsonb_build_array('missing parent_external_id'); END IF;
  IF entity='block' AND (coalesce((data->>'position')::int,0)<1 OR NOT public.englify_journey_validate_block(data->>'block_type',data->'content')) THEN errors:=errors||jsonb_build_array('invalid lesson block'); END IF;
  IF EXISTS(SELECT 1 FROM public.journey_import_rows r WHERE r.batch_id=batch.id AND r.raw_data->>'external_id'=data->>'external_id') OR EXISTS(SELECT 1 FROM public.lessons WHERE external_id=data->>'external_id') OR EXISTS(SELECT 1 FROM public.learning_units WHERE external_id=data->>'external_id') OR EXISTS(SELECT 1 FROM public.journey_chapters WHERE external_id=data->>'external_id') THEN errors:=errors||jsonb_build_array('duplicate external_id'); END IF;
  IF jsonb_array_length(errors)=0 THEN valid:=valid+1; END IF; INSERT INTO public.journey_import_rows(batch_id,row_number,raw_data,validation_errors) VALUES(batch.id,row.ordinality+1,data,errors); END LOOP;
 RETURN jsonb_build_object('batch_id',batch.id,'row_count',batch.row_count,'valid_count',valid,'rows',(SELECT jsonb_agg(to_jsonb(r) ORDER BY row_number) FROM public.journey_import_rows r WHERE batch_id=batch.id)); END $$;

CREATE OR REPLACE FUNCTION public.englify_admin_commit_journey_import(p_batch uuid,p_request_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE batch public.journey_import_batches; row public.journey_import_rows; data jsonb; new_id uuid; lesson uuid; revision uuid; imported int:=0;
BEGIN IF NOT public.englify_is_admin() THEN RAISE EXCEPTION 'Administrator access required' USING ERRCODE='42501'; END IF; IF p_request_id IS NULL THEN RAISE EXCEPTION 'Request ID required' USING ERRCODE='22023'; END IF; SELECT b.* INTO batch FROM public.journey_import_batches b WHERE b.id=p_batch AND b.created_by=auth.uid() FOR UPDATE; IF NOT FOUND THEN RAISE SQLSTATE 'PT404' USING MESSAGE='Import batch not found'; END IF; IF batch.status='committed' THEN RETURN jsonb_build_object('batch_id',batch.id,'imported',(SELECT count(*) FROM public.journey_import_rows WHERE batch_id=batch.id AND imported_id IS NOT NULL),'replayed',true); END IF;
 FOR row IN SELECT * FROM public.journey_import_rows WHERE batch_id=batch.id AND jsonb_array_length(validation_errors)=0 ORDER BY CASE raw_data->>'entity' WHEN 'chapter' THEN 1 WHEN 'unit' THEN 2 WHEN 'lesson' THEN 3 ELSE 4 END,row_number LOOP data:=row.raw_data;new_id:=NULL;
  IF data->>'entity'='chapter' THEN INSERT INTO public.journey_chapters(course_id,slug,title,description,position,external_id,lifecycle_status) VALUES((data->>'course_id')::uuid,data->>'slug',data->>'title',coalesce(data->>'description',''),(data->>'position')::int,data->>'external_id','draft') RETURNING id INTO new_id;
  ELSIF data->>'entity'='unit' THEN INSERT INTO public.learning_units(course_id,chapter_id,slug,title,position,external_id,lifecycle_status) SELECT (data->>'course_id')::uuid,c.id,data->>'slug',data->>'title',(data->>'position')::int,data->>'external_id','draft' FROM public.journey_chapters c WHERE c.external_id=data->>'parent_external_id' RETURNING learning_units.id INTO new_id;
  ELSIF data->>'entity'='lesson' THEN INSERT INTO public.lessons(course_id,unit_id,slug,title,objective,position,external_id,lifecycle_status) SELECT (data->>'course_id')::uuid,u.id,data->>'slug',data->>'title',coalesce(data->>'objective',''),(data->>'position')::int,data->>'external_id','draft' FROM public.learning_units u WHERE u.external_id=data->>'parent_external_id' RETURNING lessons.id INTO new_id;
  ELSE SELECT id INTO lesson FROM public.lessons WHERE external_id=data->>'parent_external_id' AND lifecycle_status='draft'; IF lesson IS NULL THEN RAISE EXCEPTION 'Missing draft lesson parent for block row %',row.row_number USING ERRCODE='22023'; END IF; SELECT id INTO revision FROM public.journey_lesson_revisions WHERE lesson_id=lesson AND status='draft' ORDER BY version DESC LIMIT 1; IF revision IS NULL THEN INSERT INTO public.journey_lesson_revisions(lesson_id,version,status,source,content_hash,created_by) SELECT lesson,coalesce(max(version),0)+1,'draft','curated',encode(extensions.digest('[]','sha256'),'hex'),auth.uid() FROM public.journey_lesson_revisions WHERE lesson_id=lesson RETURNING id INTO revision; END IF; INSERT INTO public.journey_lesson_blocks(revision_id,lesson_id,position,block_type,content) VALUES(revision,lesson,(data->>'position')::int,data->>'block_type',data->'content') RETURNING id INTO new_id; END IF;
  IF new_id IS NULL THEN RAISE EXCEPTION 'Missing import parent for row %',row.row_number USING ERRCODE='22023'; END IF; UPDATE public.journey_import_rows SET imported_id=new_id WHERE journey_import_rows.id=row.id; imported:=imported+1; END LOOP;
 UPDATE public.journey_import_batches SET status='committed',committed_at=now() WHERE journey_import_batches.id=batch.id; RETURN jsonb_build_object('batch_id',batch.id,'imported',imported); END $$;

REVOKE ALL ON FUNCTION public.englify_admin_stage_journey_import(uuid,text,text,jsonb),public.englify_admin_commit_journey_import(uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.englify_admin_stage_journey_import(uuid,text,text,jsonb),public.englify_admin_commit_journey_import(uuid,uuid) TO authenticated;
